import operator
from decimal import Decimal as D
from fractions import Fraction as F

def _t():
    z = 1.0 + 0j
    w = -3.14 + 2.7j
    for v in (1, 1.0, F(1), D(1), complex(1)):
        assert z == v, ('assertEqual', z, v)
        assert v == z, ('assertEqual', v, z)
    for v in (2, 2.0, F(2), D(2), complex(2)):
        assert z != v, ('assertNotEqual', z, v)
        assert v != z, ('assertNotEqual', v, z)
        assert w != v, ('assertNotEqual', w, v)
        assert v != w, ('assertNotEqual', v, w)
    for v in (1, 1.0, F(1), D(1), complex(1), 2, 2.0, F(2), D(2), complex(2), w):
        for op in (operator.le, operator.lt, operator.ge, operator.gt):
            try:
                op(*(z, v))
            except TypeError:
                pass
            try:
                op(*(v, z))
            except TypeError:
                pass
try:
    _t()
except BaseException as _e:
    print('ORACLE_EXC ' + type(_e).__name__ + ' ' + repr(str(_e)))
else:
    print('ok')
